import time, threading
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
key = bytes(range(16)); nonce=b'\x00'*12
pt = bytes(61440000)
NCHUNK = 12
chunk = len(pt)//NCHUNK
def enc_chunk(i):
    start = i*chunk
    end = start+chunk if i<NCHUNK-1 else len(pt)
    iv = nonce + (2 + start//16).to_bytes(4,'big')
    e = Cipher(algorithms.AES(key), modes.CTR(iv)).encryptor()
    return e.update(pt[start:end])
def run_threads():
    results = [None]*NCHUNK
    def worker(i):
        results[i] = enc_chunk(i)
    ts = [threading.Thread(target=worker, args=(i,)) for i in range(NCHUNK)]
    for t in ts: t.start()
    for t in ts: t.join()
    return b''.join(results)
# single thread
def single():
    e = Cipher(algorithms.AES(key), modes.CTR(nonce+b'\x00\x00\x00\x02')).encryptor()
    return e.update(pt)
def bench(f, N=10):
    f()
    t0=time.perf_counter()
    for _ in range(N): f()
    t1=time.perf_counter()
    return (t1-t0)/N*1e3
print('single ms', bench(single))
print('threads ms', bench(run_threads))
