#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <wmmintrin.h>
#include <emmintrin.h>

static inline __m128i aes_round(__m128i state, __m128i rk) {
    return _mm_aesenc_si128(state, rk);
}

int main() {
    // AES-128 key schedule
    uint8_t key[16] = {0};
    __m128i rk[11];
    rk[0] = _mm_loadu_si128((__m128i*)key);
    for (int i = 1; i <= 10; i++) {
        __m128i t = rk[i-1];
        // key expansion
        __m128i tmp = _mm_aeskeygenassist_si128(t, (i==1?1:(i==2?2:(i==3?4:(i==4?8:(i==5?16:(i==6?32:(i==7?64:(i==8?128:(i==9?27:54))))))))));
        tmp = _mm_shuffle_epi32(tmp, 0xff);
        __m128i x = _mm_xor_si128(_mm_slli_si128(t, 4), tmp);
        x = _mm_xor_si128(x, _mm_slli_si128(x, 4));
        x = _mm_xor_si128(x, _mm_slli_si128(x, 4));
        rk[i] = _mm_xor_si128(x, _mm_slli_si128(x, 4));
    }
    // encrypt a block
    __m128i state = _mm_loadu_si128((__m128i*)key);
    state = _mm_xor_si128(state, rk[0]);
    for (int i = 1; i < 10; i++) state = aes_round(state, rk[i]);
    state = _mm_aesenclast_si128(state, rk[10]);
    uint8_t out[16];
    _mm_storeu_si128((__m128i*)out, state);
    printf("ok\n");
    return 0;
}
